18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's locality. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials", expression = "java(initials(owner))")
31	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * The canonical region derived from the owner's city using the fixed
39	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or
40	     * 'UNKNOWN' when the city is not in the table.
41	     */
42	    default String locality(Owner owner) {
43	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
44	    }
45	
46	    /**
47	     * The owner's membership tier: 'SILVER' when the owner has no namesakes
48	     * (namesakeCount is 0) and an email address is present, otherwise 'BRONZE'.
49	     */
50	    default String membershipTier(Owner owner) {
51	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
52	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
53	        return hasEmail && noNamesakes ? "SILVER" : "BRONZE";
54	    }
55	
56	    /**
57	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
58	     * is the last two digits of the registrationDate year (e.g. 'SYD-SMI-0007-M26').
59	     */
60	    default String membershipNumber(Owner owner) {
61	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
62	            return null;
63	        }
64	        return String.format("%s-M%02d", owner.getCustomerCode(),
65	            owner.getRegistrationDate().getYear() % 100);
66	    }
67	
68	    /**
69	     * The upper-cased first letters of firstName and lastName, dot-separated with a
70	     * trailing dot, e.g. 'J.S.'.
71	     */
72	    default String initials(Owner owner) {
73	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
74	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
75	    }
76	
77	    /**
78	     * A stable identifier for the owner's household, derived deterministically from the
79	     * normalized last name and address (trimmed, lower-cased, whitespace collapsed).
80	     * Every owner sharing a household therefore receives the same identifier: the first
81	     * eight upper-case hex characters of the SHA-256 of '&lt;lastName&gt;|&lt;address&gt;'.
82	     */
83	    default String householdId(Owner owner) {
84	        String key = normalizeHouseholdKey(owner.getLastName()) + "|"
85	            + normalizeHouseholdKey(owner.getAddress());
86	        try {
87	            byte[] digest = MessageDigest.getInstance("SHA-256")
88	                .digest(key.getBytes(StandardCharsets.UTF_8));
89	            StringBuilder sb = new StringBuilder();
90	            for (int i = 0; i < 4; i++) {
91	                sb.append(String.format("%02X", digest[i]));
92	            }
93	            return sb.toString();
94	        }
95	        catch (java.security.NoSuchAlgorithmException e) {
96	            throw new IllegalStateException(e);
97	        }
98	    }
99	
100	    private static String normalizeHouseholdKey(String value) {
101	        if (value == null) {
102	            return "";
103	        }
104	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
105	    }
106	
107	    Owner toOwner(OwnerDto ownerDto);
108	
109	    @Mapping(target = "id", ignore = true)
110	    @Mapping(target = "pets", ignore = true)
111	    Owner toOwner(OwnerFieldsDto ownerDto);
