114	
115	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
116	
117	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
118	        OwnerPageDto ownerPageDto = new OwnerPageDto();
119	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
120	        ownerPageDto.setPage(ownerPage.getNumber());
121	        ownerPageDto.setSize(ownerPage.getSize());
122	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
123	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
124	        return ownerPageDto;
125	    }
